package com.powercms.cms.delivery;
import com.powercms.cms.publish.SiteCacheWarmupRequested; import com.powercms.cms.site.repo.SiteRepository; import org.springframework.boot.context.event.ApplicationReadyEvent; import org.springframework.context.event.EventListener; import org.springframework.stereotype.Component; import org.springframework.transaction.event.*;
@Component public class CacheWarmupEventListener { private final CacheWarmupService warmup; private final SiteRepository sites; CacheWarmupEventListener(CacheWarmupService w,SiteRepository s){warmup=w;sites=s;} @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void afterCommit(SiteCacheWarmupRequested e){try{warmup.trigger(e.siteId());}catch(RuntimeException ignored){}} @EventListener public void applicationReady(ApplicationReadyEvent event){for(var site:sites.findAll())try{warmup.trigger(site.getId());}catch(RuntimeException ignored){}} }
